const $=s=>document.querySelector(s);
const toNum=s=>{const a=s.trim().split('.');if(a.length!==4||a.some(x=>!/^\d{1,3}$/.test(x)||+x>255||(x.length>1&&x[0]==='0')))throw Error('Введи четыре числа от 0 до 255 без ведущих нулей.');return a.reduce((n,x)=>n*256+Number(x),0)};
const dotted=n=>[24,16,8,0].map(shift=>Math.floor(n/2**shift)%256).join('.');
const binary=n=>Math.floor(n).toString(2).padStart(32,'0');
function network(ip,p){const n=toNum(ip),size=2**(32-p),base=Math.floor(n/size)*size;return {n,base,last:base+size-1,size,host:n-base,mask:2**32-size}}
function lab(){try{const ip=$('#ip').value,p=+$('#prefix').value,v=network(ip,p);$('#ip-error').textContent='';$('#prefix-label').textContent=p;const rows=[['IP',v.n],['Маска',v.mask],['Сеть',v.base]];$('#bitrows').innerHTML=rows.map(([label,n])=>`<div class="bitrow"><b>${label}</b><div>${[...binary(n)].map((x,i)=>`<span class="${i<p?'net':'host'} ${i%8===7?'gap':''}">${x}</span>`).join('')}</div></div>`).join('');$('#facts').innerHTML=[['Маска',dotted(v.mask)],['Сеть',dotted(v.base)],['Последний адрес',dotted(v.last)],['Номер узла',v.host],['Узловых битов',32-p],['Всего адресов',v.size.toLocaleString('ru')]].map(([k,val])=>`<div><small>${k}</small><strong>${val}</strong></div>`).join('')}catch(e){$('#ip-error').textContent=e.message;$('#bitrows').textContent='';$('#facts').textContent=''}}
$('#ip').addEventListener('input',lab);$('#prefix').addEventListener('input',lab);lab();
$('#house').oninput=e=>{const p=+e.target.value;$('#house-number').textContent='43568'.slice(0,p);$('#flat-number').textContent='43568'.slice(p);$('#house-caption').textContent=`Дом ${'43568'.slice(0,p)} · квартира ${'43568'.slice(p)}`};
$('#octet').oninput=e=>{const s=e.target.value,n=Number(s);if(!s||!Number.isInteger(n)||n<0||n>255){$('#octet-output').textContent='От 0 до 255';$('#weights').textContent='';return}const b=n.toString(2).padStart(8,'0');$('#octet-output').textContent=b;$('#weights').textContent=(Array.from(b).flatMap((x,i)=>x==='1'?[2**(7-i)]:[]).join(' + ')||'0')+' = '+n};
for(const id of ['and-a','and-b'])$('#'+id).onclick=e=>{e.target.textContent=e.target.textContent==='1'?'0':'1';$('#and-out').textContent=Number($('#and-a').textContent)&Number($('#and-b').textContent)};
function parity(){const hosts=$('#hosts-only').checked;let count=0;$('#parity-list').innerHTML=Array.from({length:16},(_,i)=>{const n=toNum('192.168.32.160')+i,even=binary(n).replaceAll('0','').length%2===0,excluded=hosts&&(i===0||i===15);if(even&&!excluded)count++;return `<span class="${excluded?'excluded':even?'even':''}">.${160+i}<small>${binary(n).replaceAll('0','').length} ед.</small></span>`}).join('');$('#parity-total').textContent=`Подходящих адресов: ${count}. Синим отмечены чётные, зачёркнутые исключены.`}$('#hosts-only').onchange=parity;parity();
for(const button of document.querySelectorAll('[data-copy]'))button.onclick=async()=>{try{await navigator.clipboard.writeText(button.parentElement.querySelector('pre').textContent);button.textContent='Скопировано';setTimeout(()=>button.textContent='Копировать',1800)}catch{button.textContent='Выдели код и скопируй вручную'}};
const questions=[
['Номер узла','IP 232.126.150.18, маска 255.255.240.0. Найди номер узла в подсети.','1554',['Переведи третий октет маски: 240 = 11110000.','Сетевых битов 20, узловых: 12.','У третьего октета IP сохрани четыре младших бита: 150 AND 15 = 6.','Номер узла = 6 × 256 + 18.','Можно вычесть адрес сети 232.126.144.0 из IP.'],'Узловая часть: 0110 00010010₂. Это 6 × 256 + 18 = 1554.',1],
['Закрепление: номер узла','IP 206.158.124.67, маска 255.255.224.0. Найди номер узла.','7235',['224 = 11100000.','Свободны пять разрядов третьего октета и весь четвёртый.','124 AND 31 = 28.','28 × 256 + 67.'],'Сеть 206.158.96.0. Узловая часть равна 28 × 256 + 67 = 7235.'],
['Собери адрес сети буквами','IP 240.144.182.134, маска 255.255.248.0. Таблица: A=0, B=134, C=144, D=176, E=182, F=240, G=248, H=6. Введи четыре буквы в нужном порядке.','FCDA',['Первые два октета сохраняются, последний станет нулём.','182 = 10110110, 248 = 11111000.','AND даёт 10110000 = 176.','Сеть 240.144.176.0.','Сопоставь каждое число с буквой.'],'240 → F, 144 → C, 176 → D, 0 → A. Ответ FCDA.',3],
['Ещё один адрес сети','IP 217.9.235.133, маска 255.255.248.0. A=255, B=9, C=217, D=216, E=137, F=232, G=8, H=0. Введи буквы адреса сети.','CBFH',['235 AND 248 = 232.','Четвёртый октет обнуляется.','Сеть 217.9.232.0.'],'217 → C, 9 → B, 232 → F, 0 → H.'],
['Граница внутри октета','IP 255.111.32.96, маска 255.255.192.0. Найди адрес сети в десятичной записи через точки.','255.111.0.0',['192 = 11000000.','32 = 00100000.','32 AND 192 = 0.'],'Первые два октета сохраняются; третий и четвёртый обнуляются. Сеть 255.111.0.0.'],
['Сколько компьютеров?','Маска 255.255.254.0. Сколько адресов доступно устройствам, если адрес сети и широковещательный исключаются?','510',['В третьем октете один ноль, в четвёртом: восемь.','Всего h = 9.','2⁹ = 512 адресов.','Вычти два служебных адреса.'],'2⁹ − 2 = 510.',6],
['Закрепление: число узлов','Для маски 255.255.248.0 посчитай адреса устройств, исключая два крайних.','2046',['248 = 11111000.','Три нуля в третьем октете и восемь в четвёртом.','2¹¹ − 2.'],'2¹¹ − 2 = 2046.'],
['Чётное число единиц','Для сети 192.168.32.160/28 найди количество всех IP-адресов с чётной суммой единиц. Два крайних адреса включаются.','8',['В маске четыре нуля.','Всего 16 адресов.','При изменении свободного бита чётность меняется.'],'Половина из 16 адресов: 8.'],
['Два левых и два правых байта','Сеть задана IP 253.112.169.12 и маской 255.255.254.0. В скольких адресах единиц справа не меньше, чем слева?','46',['Слева 7 + 3 = 10 единиц.','Справа три единицы фиксированы.','Свободны девять битов.','Нужно 7, 8 или 9 единиц в свободной части.'],'C(9,7) + C(9,8) + C(9,9) = 36 + 9 + 1 = 46.'],
['Тренировочный вариант: нечётная сумма','Для 192.168.32.160/28 посчитай все адреса с нечётной суммой единиц.','8',['Всего 16 адресов.','Сопоставь адреса парами, меняя последний бит.'],'В каждой паре один чётный и один нечётный адрес. Ответ 8.'],
['Наименьший последний байт маски','Узел 111.81.88.168 относится к сети 111.81.88.160. Найди минимальный последний октет маски.','224',['Сравни 168 = 10101000 и 160 = 10100000.','Проверь допустимые байты: 0, 128, 192, 224, 240, 248, 252, 254, 255.','При 192 получается 128; при 224: 160.'],'10101000 AND 11100000 = 10100000. Минимальный подходящий октет: 224.'],
['Наибольший префикс','Узел 93.138.70.47 относится к сети 93.138.64.0. Найди наибольшее число единиц в маске.','21',['Первые два октета дают 16 единиц.','70 = 01000110, 64 = 01000000.','Для /21 маска третьего октета 11111000.','При /22 сеть станет 93.138.68.0.'],'Максимальный префикс /21: 16 + 5 = 21 единица.'],
['Сколько масок подходят?','Узел 175.122.80.13, адрес сети 175.122.80.0. В сети не менее 60 устройств без двух служебных адресов. Сколько возможных масок?','7',['Нужно 2ʰ − 2 ≥ 60, то есть h ≥ 6.','Значит префикс не больше 26.','Чтобы сохранить сеть, префикс должен быть не меньше 20.','Подходят /20, /21, …, /26.'],'Всего семь масок.'],
['Порядковый номер узла','IP 162.198.0.157, маска 255.255.255.224. Найди номер узла относительно адреса сети.','29',['Пять младших битов четвёртого октета: узловые.','157 = 10011101.','Узловая часть 11101₂.'],'Сеть заканчивается на 128. 157 − 128 = 29.'],
['Параметр A в маске','IP 255.211.33.160, маска 255.255.A.0. Найди минимальное A, чтобы у каждого адреса единиц в двух левых байтах было не меньше, чем в двух правых.','240',['Слева всегда 8 + 5 = 13 единиц.','Для всех адресов проверь максимум единиц справа.','Перебери допустимые A.','При A=224 справа максимум 14; при A=240: 13.'],'A=240: третий октет фиксирует 0010, давая одну единицу. Свободны 4+8 битов: максимум 13. При меньших A максимум превышает 13.'],
['Параметр A в IP','IP 32.0.A.5, маска 255.255.240.0. Найди минимальное A, чтобы для всех адресов единиц слева было не больше, чем справа.','16',['Слева ровно одна единица.','Минимум справа достигается при нулевых свободных битах.','Нужна хотя бы одна единица в четырёх старших битах A.'],'При A от 0 до 15 старшая тетрада нулевая. Первое подходящее значение: 16 (00010000₂).']
];
const definition = 'В терминологии сетей TCP/IP маска подсети представляет собой 32-разрядное двоичное число, определяющее, какие разряды IP-адреса относятся к адресу сети, а какие: к адресу узла. В маске сначала идут единицы, затем нули. Адрес сети получается поразрядной конъюнкцией IP-адреса узла и маски.';
const tables={2:[0,134,144,176,182,240,248,6],3:[255,9,217,216,137,232,8,0],4:[0,32,64,96,100,111,192,255]};
const inputData={0:['232.126.150.18','255.255.240.0'],1:['206.158.124.67','255.255.224.0'],2:['240.144.182.134','255.255.248.0'],3:['217.9.235.133','255.255.248.0'],4:['255.111.32.96','255.255.192.0'],7:['192.168.32.160','255.255.255.240'],8:['253.112.169.12','255.255.254.0'],9:['192.168.32.160','255.255.255.240'],13:['162.198.0.157','255.255.255.224'],14:['255.211.33.160','255.255.A.0'],15:['32.0.A.5','255.255.240.0']};
const tableHtml=(values,caption)=>`<div class="task-table-wrap"><table class="task-table"><caption>${caption}</caption><thead><tr>${values.map((_,i)=>`<th scope="col">${String.fromCharCode(65+i)}</th>`).join('')}</tr></thead><tbody><tr>${values.map(v=>`<td>${v}</td>`).join('')}</tr></tbody></table></div>`;
function statement(id,text){let html=`<div class="task-condition"><p>${definition}</p>`;if(inputData[id])html+=`<dl class="task-given"><div><dt>IP-адрес узла</dt><dd>${inputData[id][0]}</dd></div><div><dt>Маска подсети</dt><dd>${inputData[id][1]}</dd></div></dl>`;
if(tables[id]){html+=`<p>По заданным IP-адресу узла и маске определите адрес сети. Выберите из таблицы четыре числа, соответствующие четырём байтам адреса сети. Запишите в нужном порядке соответствующие им <b>латинские буквы без точек и пробелов</b>.</p>${tableHtml(tables[id],'Варианты байтов адреса сети')}<details class="answer-format"><summary>Пример записи ответа</summary><p>Если получен адрес сети 192.168.128.0, а варианты приведены в таблице ниже:</p>${tableHtml([128,168,255,8,127,0,17,192],'Таблица только для примера')}<p>192 соответствует H, 168: B, 128: A, 0: F. Ответ: <b>HBAF</b>. Этот пример не является ответом на основную задачу.</p></details>`}
else if(id===0||id===1||id===13)html+='<p>Определите номер компьютера в данной подсети. Нумерация начинается с нуля: номер узла равен разности между IP-адресом компьютера и адресом сети. В ответе укажите только число.</p>';
else if(id===7||id===9)html+=`<p>Определите, сколько IP-адресов этой сети имеют ${id===7?'чётное':'нечётное'} количество единиц в двоичной записи полного IP-адреса. Учитываются все адреса сети, включая адрес сети и широковещательный адрес. В ответе укажите только число.</p>`;
else if(id===8)html+='<p>Сколько в этой сети IP-адресов, у которых суммарное количество единиц в правых двух байтах двоичной записи не меньше суммарного количества единиц в левых двух байтах? Учитывайте все адреса сети. В ответе укажите только число.</p>';
else if(id===14||id===15)html+=`<p>${text}</p><p>Условие должно выполняться для <b>каждого</b> IP-адреса полученной сети. В ответе укажите только найденное десятичное значение A.</p>`;
else html+=`<p>${text}</p><p>В ответе укажите только число.</p>`;
return html+'</div>'}
questions[4][2]='HFAA';questions[4][4]='Адрес сети 255.111.0.0. По таблице: 255 → H, 111 → F, 0 → A, 0 → A. Ответ HFAA.';
for(const el of document.querySelectorAll('[data-q]')){const id=+el.dataset.q,[title,text,answer,hints,solution,extra]=questions[id];el.id='q'+id;let used=0;el.innerHTML=`<span class="eyebrow">ПРАКТИКА</span><h3>${title}</h3>${statement(id,text)}<form><label>Твой ответ<input aria-label="Ответ: ${title}" autocomplete="off"></label><button>Проверить</button></form><p class="result" role="status"></p><div class="quiz-actions"><button class="hint">Подсказка</button><button class="solution">Показать разбор</button></div><ol class="hints"></ol><div class="solution-text" hidden></div><p class="extra"></p>`;el.querySelector('form').onsubmit=e=>{e.preventDefault();const value=el.querySelector('input').value.trim().toUpperCase().replaceAll(' ','');el.querySelector('.result').textContent=value===answer.toUpperCase()?'Верно! Можно переходить дальше.':'Пока не совпадает. Проверь вычисления или открой подсказку.'};el.querySelector('.hint').onclick=e=>{if(used<hints.length){const li=document.createElement('li');li.textContent=hints[used++];el.querySelector('.hints').append(li)}e.target.textContent=`Подсказки: ${used}/${hints.length}`;e.target.disabled=used===hints.length;if(used>=2&&extra!==undefined)el.querySelector('.extra').innerHTML=`Немного закрепления: <a href="#q${extra}">реши похожую задачу</a>.`};el.querySelector('.solution').onclick=e=>{const panel=el.querySelector('.solution-text');panel.hidden=!panel.hidden;panel.textContent=`Ответ: ${answer}. ${solution}`;e.target.textContent=panel.hidden?'Показать разбор':'Скрыть разбор'}}

for(const b of document.querySelectorAll('.micro-answer'))b.onclick=()=>{b.closest('.microcheck').querySelector('.micro-feedback').textContent=b.dataset.feedback};
